def load_json(path: Path) -> Any:
    """Load one UTF-8 JSON artifact from the candidate."""

    return json.loads(path.read_text(encoding="utf-8-sig"))


def sha256(path: Path) -> str:
    """Return a streaming SHA-256 digest for an asset."""

    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(65536), b""):
            digest.update(chunk)
    return digest.hexdigest()


def current_product_revision() -> str:
    """Return the current non-self-referential product revision digest."""

    revision, _manifest = product_revision(ROOT)
    return revision


def validate_revision_binding(receipt: dict[str, Any], label: str) -> list[str]:
    """Require one generated receipt to name the current product revision."""

    if receipt.get("product_revision_sha256") != current_product_revision():
        return [f"{label} product revision does not match the current candidate"]
    return []


def load_prompt_optimizer() -> Any:
    """Load the shipped optimizer module from the release candidate."""

    spec = importlib.util.spec_from_file_location("candidate_prompt_optimizer", MODULE_PATH)
    if spec is None or spec.loader is None:
        raise ImportError(f"cannot load optimizer module from {MODULE_PATH}")
    module = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = module
    spec.loader.exec_module(module)
    return module


def paeth(left: int, up: int, upper_left: int) -> int:
    """Return the PNG Paeth predictor value for three neighboring bytes."""

    estimate = left + up - upper_left
    distances = (abs(estimate - left), abs(estimate - up), abs(estimate - upper_left))
    return (left, up, upper_left)[distances.index(min(distances))]


def decode_png_rgba(path: Path) -> tuple[int, int, list[bytes]]:
    """Decode a non-interlaced 8-bit RGBA PNG using only the standard library."""

    data = path.read_bytes()
    if data[:8] != b"\x89PNG\r\n\x1a\n":
        raise ValueError("not a PNG")
    offset = 8
    width = height = bit_depth = color_type = interlace = None
    compressed = bytearray()
    while offset < len(data):
        length = struct.unpack(">I", data[offset : offset + 4])[0]
        kind = data[offset + 4 : offset + 8]
        payload = data[offset + 8 : offset + 8 + length]
        offset += 12 + length
        if kind == b"IHDR":
            width, height, bit_depth, color_type, _, _, interlace = struct.unpack(">IIBBBBB", payload)
        elif kind == b"IDAT":
            compressed.extend(payload)
        elif kind == b"IEND":
            break
    if None in (width, height, bit_depth, color_type, interlace):
        raise ValueError("missing IHDR")
    if bit_depth != 8 or color_type != 6 or interlace != 0:
        raise ValueError(
            f"expected non-interlaced 8-bit RGBA, got depth={bit_depth} type={color_type} interlace={interlace}"
        )
    raw = zlib.decompress(bytes(compressed))
    stride = width * 4
    rows: list[bytes] = []
    previous = bytearray(stride)
    cursor = 0
    for _ in range(height):
        filter_type = raw[cursor]
        cursor += 1
        source = raw[cursor : cursor + stride]
        cursor += stride
        row = bytearray(stride)
        for index, value in enumerate(source):
            left = row[index - 4] if index >= 4 else 0
            up = previous[index]
            upper_left = previous[index - 4] if index >= 4 else 0
            if filter_type == 0:
                decoded = value
            elif filter_type == 1:
                decoded = value + left
            elif filter_type == 2:
                decoded = value + up
            elif filter_type == 3:
                decoded = value + ((left + up) // 2)
            elif filter_type == 4:
                decoded = value + paeth(left, up, upper_left)
            else:
                raise ValueError(f"unsupported PNG filter {filter_type}")
            row[index] = decoded & 0xFF
        rows.append(bytes(row))
        previous = row
    return width, height, rows


def validate_png(path: Path, expected: tuple[int, int, bool]) -> list[str]:
    """Validate PNG dimensions, corner alpha, and transparent-mark coverage."""

    try:
        width, height, rows = decode_png_rgba(path)
    except (OSError, ValueError, zlib.error, struct.error) as exc:
        return [f"{path.relative_to(ROOT)}: PNG decode failed: {exc}"]
    errors: list[str] = []
    expected_width, expected_height, transparent = expected
    if (width, height) != (expected_width, expected_height):
        errors.append(f"{path.relative_to(ROOT)}: expected {expected_width}x{expected_height}, got {width}x{height}")
    corners = (
        rows[0][3],
        rows[0][(width - 1) * 4 + 3],
        rows[height - 1][3],
        rows[height - 1][(width - 1) * 4 + 3],
    )
    expected_alpha = 0 if transparent else 255
    if any(alpha != expected_alpha for alpha in corners):
        state = "transparent" if transparent else "opaque"
        errors.append(f"{path.relative_to(ROOT)}: {state} asset corners have incorrect alpha")
    if transparent:
        opaque_pixels = sum(1 for row in rows for alpha in row[3::4] if alpha >= 240)
        coverage = opaque_pixels / (width * height)
        if not 0.03 <= coverage <= 0.55:
            errors.append(f"{path.relative_to(ROOT)}: subject coverage {coverage:.3f} is outside 0.03-0.55")
    return errors


def validate_required_files() -> list[str]:
    """Return every missing path required by the standalone candidate."""

    return [f"required file is missing: {relative}" for relative in REQUIRED_FILES if not (ROOT / relative).is_file()]


def validate_file_shape() -> list[str]:
    """Reject symlinks, generated bytecode, and oversized candidate files."""

    errors: list[str] = []
    for path in ROOT.rglob("*"):
        relative = path.relative_to(ROOT)
        if ".git" in relative.parts:
            continue
        if path.is_symlink():
            errors.append(f"symlink is not allowed: {relative}")
            continue
        if not path.is_file():
            continue
        if "__pycache__" in relative.parts or path.suffix == ".pyc":
            errors.append(f"generated Python cache is not allowed: {relative}")
        if path.stat().st_size > MAX_FILE_BYTES:
            errors.append(f"file exceeds {MAX_FILE_BYTES} bytes: {relative}")
    return errors


def validate_text_safety() -> list[str]:
    """Scan public text artifacts for secrets, private markers, paths, and placeholders."""

    errors: list[str] = []
    for path in ROOT.rglob("*"):
        relative = path.relative_to(ROOT)
        if ".git" in relative.parts:
            continue
        if not path.is_file() or (path.suffix.lower() not in TEXT_SUFFIXES and path.name != "LICENSE"):
            continue
        try:
            text = path.read_text(encoding="utf-8-sig")
        except UnicodeDecodeError:
            continue
        lower = text.lower()
        for marker in PRIVATE_MARKERS:
            if marker in lower:
                errors.append(f"private marker {marker!r} found in {relative}")
        for pattern in SECRET_PATTERNS:
            if pattern.search(text):
                errors.append(f"secret-like value matched {pattern.pattern!r} in {relative}")
        for pattern in ABSOLUTE_PATH_PATTERNS:
            if pattern.search(text):
                errors.append(f"absolute user path matched {pattern.pattern!r} in {relative}")
        placeholders = ("[" + "todo:", "[" + "todo]")
        if any(marker in lower for marker in placeholders):
            errors.append(f"TODO placeholder found in {relative}")
    return errors


