def validate_cross_platform_packaging() -> list[str]:
    """Validate public policy, funding, submission, and Router-bridge surfaces."""

    errors: list[str] = []
    try:
        funding = (ROOT / ".github" / "FUNDING.yml").read_text(encoding="utf-8")
        readme = (ROOT / "README.md").read_text(encoding="utf-8")
        privacy = (ROOT / "PRIVACY.md").read_text(encoding="utf-8")
        terms = (ROOT / "TERMS.md").read_text(encoding="utf-8")
        bridge = (ROOT / "docs" / "AGENT-SMITH-ROUTER-BRIDGE.md").read_text(encoding="utf-8")
        measurement = (ROOT / "docs" / "LAUNCH-MEASUREMENT.md").read_text(encoding="utf-8")
        skill = (PLUGIN / "skills" / "prompt-optimizer" / "SKILL.md").read_text(encoding="utf-8")
        submission = load_json(ROOT / "submission" / "openai-plugin-submission.json")
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        return [f"cross-platform packaging failed: {exc}"]
    if funding.strip() != "github: [SpannDaMan]":
        errors.append("FUNDING.yml must contain only the approved SpannDaMan GitHub Sponsors target")
    for required in ("OpenAI/Codex", "Claude Code", "Agent Smith Router", "FUNDING.yml"):
        if required not in readme:
            errors.append(f"README is missing cross-platform public-readiness marker: {required}")
    if "does not send prompts" not in privacy or "does not include telemetry" not in privacy:
        errors.append("PRIVACY.md must state the no-upload and no-telemetry boundaries")
    if "does not prove semantic equivalence" not in terms:
        errors.append("TERMS.md must retain the semantic-equivalence limitation")
    if "does not guarantee a better route" not in bridge:
        errors.append("Router bridge must reject a guaranteed routing-improvement claim")
    if "Do not use stars alone" not in measurement:
        errors.append("launch measurement must reject stars-only success")
    if "python <plugin-root>/scripts/prompt_optimizer.py" not in skill:
        errors.append("bundled skill must document the package-relative CLI path")
    if not isinstance(submission, dict):
        errors.append("OpenAI submission packet must be a JSON object")
    else:
        if submission.get("submission_type") != "skills_only":
            errors.append("OpenAI submission packet must declare skills_only")
        if len(submission.get("positive_tests", [])) != 5:
            errors.append("OpenAI submission packet must contain five positive tests")
        if len(submission.get("negative_tests", [])) != 3:
            errors.append("OpenAI submission packet must contain three negative tests")
        if submission.get("publication_action") != "none":
            errors.append("OpenAI submission packet must record no publication action")
    return errors


