def validate_logo_provenance() -> list[str]:
    """Require one hash-locked browser GPT Image 2 source and source-only packaging."""

    errors: list[str] = []
    manifest_path = PLUGIN / "assets" / "Logo Generation Manifest 200826.json"
    try:
        manifest = load_json(manifest_path)
    except (OSError, json.JSONDecodeError) as exc:
        return [f"logo generation manifest failed: {exc}"]
    expected_relative = "plugins/prompt-optimizer/assets/Prompt Optimizer Voice-to-Prompt GPT Image 2 Master 200826.png"
    master_path = ROOT / expected_relative
    if manifest.get("canonical_master") != expected_relative:
        errors.append("logo manifest canonical_master mismatch")
    if manifest.get("source_type") != "original_browser_download":
        errors.append("logo manifest source_type must be original_browser_download")
    if "GPT Image 2" not in str(manifest.get("generation_mode", "")):
        errors.append("logo manifest must record GPT Image 2 generation")
    if manifest.get("local_edit_status") != "none":
        errors.append("logo manifest must record no local edits")
    crop = manifest.get("source_crop")
    if not isinstance(crop, dict):
        errors.append("logo manifest must record a deterministic source_crop")
    else:
        try:
            crop_x = int(crop["x"])
            crop_y = int(crop["y"])
            crop_width = int(crop["width"])
            crop_height = int(crop["height"])
            master_width = int(manifest["master_width"])
            master_height = int(manifest["master_height"])
        except (KeyError, TypeError, ValueError):
            errors.append("logo manifest source_crop is incomplete")
        else:
            if crop_width <= 0 or crop_height <= 0 or crop_width != crop_height:
                errors.append("logo manifest source_crop must be a positive square")
            if crop_x < 0 or crop_y < 0 or crop_x + crop_width > master_width or crop_y + crop_height > master_height:
                errors.append("logo manifest source_crop exceeds master bounds")
    if master_path.is_file():
        actual = hashlib.sha256(master_path.read_bytes()).hexdigest()
        if actual != str(manifest.get("master_sha256", "")).casefold():
            errors.append("canonical logo master hash mismatch")
    for retired in (
        "Prompt Optimizer Mini Logo 120826.png",
        "prompt-optimizer-mark.svg",
        "Prompt Optimizer GPT Image 2 Master 140826.png",
        "Prompt Optimizer GPT Image 2 Prompt 140826.md",
        "Logo Generation Manifest 140826.json",
    ):
        if (PLUGIN / "assets" / retired).exists():
            errors.append(f"retired local logo source still exists: {retired}")
    try:
        script = (ROOT / "tools" / "render_brand_assets.ps1").read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as exc:
        errors.append(f"brand renderer read failed: {exc}")
    else:
        for required in ("Place-Master", "DrawImage", "master_sha256", "original_browser_download", "source_crop"):
            if required not in script:
                errors.append(f"brand renderer is missing source-only control: {required}")
        for forbidden in ("Draw-RouteKitMark", "Draw-OptimizerMark", "function Draw-Mark", "function Mark(", "FillEllipse", "FillPolygon", "DrawLines", "DrawPath", "GraphicsPath"):
            if forbidden.casefold() in script.casefold():
                errors.append(f"brand renderer contains prohibited logo-origin operation: {forbidden}")
    return errors


def validate_logo_selection_evidence() -> list[str]:
    """Bind the operator-selected visual promotion to exact source and derivative bytes."""

    path = ROOT / "validation" / "Logo Selection and Promotion 200826.json"
    try:
        receipt = load_json(path)
    except (OSError, json.JSONDecodeError) as exc:
        return [f"logo selection evidence failed: {exc}"]

    errors: list[str] = []
    if receipt.get("review_type") != "operator_selected_visual_promotion" or receipt.get("status") != "pass":
        errors.append("logo selection receipt must record a passing operator-selected visual promotion")
    errors.extend(validate_revision_binding(receipt, "logo selection receipt"))

    selection = receipt.get("operator_selection")
    if not isinstance(selection, dict) or selection.get("direction") != "Voice-to-Prompt":
        errors.append("logo selection receipt must identify Voice-to-Prompt")
    elif selection.get("status") != "locked" or selection.get("selection_scope") != "private_release_candidate_only":
        errors.append("logo selection receipt must remain locked to the private release candidate")

    source = receipt.get("canonical_source")
    expected_source = "plugins/prompt-optimizer/assets/Prompt Optimizer Voice-to-Prompt GPT Image 2 Master 200826.png"
    if not isinstance(source, dict) or source.get("path") != expected_source:
        errors.append("logo selection receipt canonical source path is invalid")
    else:
        source_path = ROOT / expected_source
        if not source_path.is_file() or source.get("sha256") != file_sha256(source_path):
            errors.append("logo selection receipt canonical source hash is stale")
        if source.get("source_type") != "original_browser_download" or source.get("local_edit_status") != "none":
            errors.append("logo selection receipt must preserve the original browser source")

    provenance = receipt.get("provenance")
    expected_provenance = {
        "prompt_path": "plugins/prompt-optimizer/assets/Prompt Optimizer Voice-to-Prompt GPT Image 2 Prompt 200826.md",
        "manifest_path": "plugins/prompt-optimizer/assets/Logo Generation Manifest 200826.json",
    }
    if not isinstance(provenance, dict):
        errors.append("logo selection receipt provenance is missing")
    else:
        for field, expected_path in expected_provenance.items():
            hash_field = field.replace("_path", "_sha256")
            artifact = ROOT / expected_path
            if provenance.get(field) != expected_path or not artifact.is_file() or provenance.get(hash_field) != file_sha256(artifact):
                errors.append(f"logo selection receipt {field} binding is stale")

    packaging = receipt.get("source_only_packaging")
    derivatives = packaging.get("derivatives") if isinstance(packaging, dict) else None
    if not isinstance(packaging, dict) or any(packaging.get(flag) is not False for flag in ("geometry_changed", "redraw_used", "recolor_used", "inpainting_used")):
        errors.append("logo selection receipt must record source-only packaging")
    if not isinstance(derivatives, dict) or not derivatives:
        errors.append("logo selection receipt derivative hashes are missing")
    else:
        for relative, expected_hash in derivatives.items():
            artifact = ROOT / relative
            if not artifact.is_file() or expected_hash != file_sha256(artifact):
                errors.append(f"logo selection derivative hash is stale: {relative}")

    actual_size = receipt.get("actual_size_qa")
    if not isinstance(actual_size, dict) or actual_size.get("status") != "pass":
        errors.append("logo selection actual-size QA must pass")
    else:
        qa_path = ROOT / str(actual_size.get("path", ""))
        if not qa_path.is_file() or actual_size.get("sha256") != file_sha256(qa_path):
            errors.append("logo selection actual-size QA hash is stale")

    functional_delta = receipt.get("functional_delta")
    if not isinstance(functional_delta, dict) or functional_delta.get("compiler_behavior_changed") is not False:
        errors.append("logo selection receipt must record no compiler behavior change")
    if receipt.get("publication_action") != "none":
        errors.append("logo selection receipt must record no publication action")
    return errors


