def validate_skill_boundary() -> list[str]:
    """Keep the bundled skill compiler-only and verify its controlled transcript."""

    skill_path = PLUGIN / "skills" / "prompt-optimizer" / "SKILL.md"
    receipt_path = ROOT / "validation" / "Skill Boundary Verification 120826.json"
    transcript_path = ROOT / "validation" / "Skill Boundary Transcript 120826.md"
    try:
        skill = skill_path.read_text(encoding="utf-8")
        receipt = load_json(receipt_path)
        transcript = transcript_path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        return [f"skill boundary evidence failed: {exc}"]
    errors: list[str] = []
    required = "This skill is a compiler only: do not execute the source task or the compiled prompt."
    if required not in skill:
        errors.append("skill must contain the compiler-only handoff")
    if "keep the json packet as evidence and continue" in skill.lower():
        errors.append("skill must not continue into source-task execution")
    if receipt.get("status") != "pass" or receipt.get("source_task_executed") is not False:
        errors.append("controlled skill boundary verification must end without source-task execution")
    if receipt.get("transcript_path") != "validation/Skill Boundary Transcript 120826.md":
        errors.append("skill boundary verification transcript path is invalid")
    if receipt.get("transcript_sha256") != file_sha256(transcript_path):
        errors.append("skill boundary verification transcript hash is stale")
    if "Source task execution observed: `false`" not in transcript or "Compiled artifact returned: `true`" not in transcript:
        errors.append("controlled skill transcript does not establish compiler-only termination")
    errors.extend(validate_revision_binding(receipt, "skill boundary verification"))
    if receipt.get("publication_action") != "none":
        errors.append("skill boundary verification must record no publication action")
    return errors


def validate_claims() -> list[str]:
    """Reject unqualified preservation or performance claims in discovery copy."""

    paths = (ROOT / "README.md", ROOT / "BRAND.md", PLUGIN / ".codex-plugin" / "plugin.json")
    patterns = (
        re.compile(r"without losing constraints", re.IGNORECASE),
        re.compile(r"guarantee(?:d|s)? (?:constraint|semantic|prompt)", re.IGNORECASE),
        re.compile(r"semantic equivalence is proven", re.IGNORECASE),
        re.compile(r"improves every prompt", re.IGNORECASE),
    )
    errors: list[str] = []
    for path in paths:
        try:
            text = path.read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError) as exc:
            errors.append(f"claims scan failed for {path.relative_to(ROOT)}: {exc}")
            continue
        for pattern in patterns:
            if pattern.search(text):
                errors.append(f"unqualified claim matched in {path.relative_to(ROOT)}: {pattern.pattern}")
    return errors


def validate_private_pilot_contract() -> list[str]:
    """Require a consistent post-release maintainer-pilot contract."""

    paths = (
        ROOT / "MAINTAINER-PILOT.md",
        ROOT / "README.md",
        ROOT / "PUBLICATION-GATE.md",
        ROOT / "RELEASE-CHECKLIST.md",
    )
    try:
        texts = {path.name: path.read_text(encoding="utf-8") for path in paths}
    except (OSError, UnicodeDecodeError) as exc:
        return [f"private pilot contract read failed: {exc}"]
    combined = "\n".join(texts.values()).lower()
    errors: list[str] = []
    for forbidden in (
        "must finish before any public-release decision",
        "no public repository",
        "private maintainer pilot that precedes",
    ):
        if forbidden in combined:
            errors.append(f"maintainer pilot retains superseded pre-publication gate: {forbidden}")
    pilot = texts["MAINTAINER-PILOT.md"].lower()
    for required in (
        "spanndaman",
        "no more than five",
        "private issue or feedback log",
        "triage twice",
        "change control",
        "stop conditions",
        "support minutes",
        "day-30 decision",
        "post-release",
        "public repository may remain live",
        "explicitly overridden",
    ):
        if required not in pilot:
            errors.append(f"private pilot contract is missing: {required}")
    return errors


def validate_png_assets() -> tuple[list[str], dict[str, str]]:
    """Validate every required PNG once and return its stable digest map."""

    errors: list[str] = []
    asset_hashes: dict[str, str] = {}
    for relative, expected in EXPECTED_PNGS.items():
        path = ROOT / relative
        if not path.is_file():
            errors.append(f"PNG asset is missing: {relative}")
            continue
        errors.extend(validate_png(path, expected))
        try:
            asset_hashes[relative] = sha256(path)
        except OSError as exc:
            errors.append(f"cannot hash PNG asset {relative}: {exc}")
    return errors, asset_hashes


def run_validation() -> dict[str, Any]:
    """Run every release check once and return one internally consistent receipt."""

    png_errors, asset_hashes = validate_png_assets()
    check_errors = {
        "required_files": validate_required_files(),
        "portable_file_shape": validate_file_shape(),
        "text_safety": validate_text_safety(),
        "metadata": validate_metadata(),
        "cross_platform_packaging": validate_cross_platform_packaging(),
        "json_artifacts": validate_json_artifacts(),
        "logo_provenance": validate_logo_provenance(),
        "logo_selection_evidence": validate_logo_selection_evidence(),
        "sample_analysis": validate_sample_analysis(),
        "sample_trace": validate_sample_trace(),
        "one_command_demo": validate_demo(),
        "native_prompt_agent_eval": validate_eval_evidence(),
        "package_evidence": validate_package_evidence(),
        "codex_plugin_evidence": validate_plugin_evidence(),
        "claude_plugin_evidence": validate_claude_plugin_evidence(),
        "json_schema_evidence": validate_schema_evidence(),
        "skill_boundary": validate_skill_boundary(),
        "claims_integrity": validate_claims(),
        "private_pilot_contract": validate_private_pilot_contract(),
        "review_evidence": validate_review_evidence(),
        "png_assets": png_errors,
    }
    errors = sorted({error for group in check_errors.values() for error in group})
    evidence_hashes = {
        relative: file_sha256(ROOT / relative)
        for relative in EVIDENCE_FILES
        if (ROOT / relative).is_file()
    }
    return {
        "status": "pass" if not errors else "fail",
        "candidate": "prompt-optimizer 0.1.0",
        "product_revision_sha256": current_product_revision(),
        "root": ".",
        "checks": {name: "pass" if not group else "fail" for name, group in check_errors.items()},
        "asset_sha256": asset_hashes,
        "evidence_sha256": evidence_hashes,
        "errors": errors,
    }


def main() -> int:
    """Run the release validator CLI and render human or JSON output."""

    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--json", action="store_true", help="Emit the full JSON validation receipt.")
    args = parser.parse_args()
    result = run_validation()
    if args.json:
        print(json.dumps(result, indent=2))
    elif result["status"] == "pass":
        print("PASS: Prompt Optimizer release candidate")
    else:
        print("FAIL: Prompt Optimizer release candidate", file=sys.stderr)
        for error in result["errors"]:
            print(f"- {error}", file=sys.stderr)
    return 0 if result["status"] == "pass" else 1


if __name__ == "__main__":
    raise SystemExit(main())
